class Queue {
  constructor() { this.items = []; }
  enqueue(x) { this.items.push(x); }
  dequeue() { return this.items.shift(); }
}
const q = new Queue();
q.enqueue('a');
q.enqueue('b');
console.log(q.dequeue());
console.log(q.dequeue());
// dequeue is O(n): shift() moves every element one slot

